  "inlineSchema": "// Prisma schema for Coffee POS System\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider  = \"postgresql\"\n  url       = env(\"DATABASE_URL\")\n  directUrl = env(\"DIRECT_URL\")\n}\n\n// 1. Quản lý Bàn & Phòng\nmodel Table {\n  id        String   @id @default(uuid())\n  name      String // VD: \"Bàn 1-Phòng thường\"\n  area      String // \"Phòng thường\", \"Phòng lạnh\"...\n  occupied  Boolean  @default(false)\n  groupId   String? // Dùng khi gộp nhiều bàn lại với nhau\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  orders    Order[]\n}\n\n// 2. Thực đơn Món Ăn / Đồ Uống\nmodel Product {\n  id          String       @id @default(uuid())\n  name        String\n  price       Float\n  category    String // \"Cà Phê\", \"Trà Trái Cây\", \"Đá Xay\", \"Bánh Ngọt\"\n  image       String?\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n  orderItems  OrderItem[]\n  recipeItems RecipeItem[]\n}\n\n// 3. Đơn Hàng (Hóa Đơn Bán Hàng)\nmodel Order {\n  id            String      @id // Mã đơn chuẩn: DH-001-08112026\n  tableId       String?\n  table         Table?      @relation(fields: [tableId], references: [id], onDelete: SetNull)\n  staffId       String?\n  staff         Staff?      @relation(fields: [staffId], references: [id], onDelete: SetNull)\n  subTotal      Float\n  discount      Float       @default(0)\n  vat           Float       @default(0)\n  total         Float\n  paymentMethod String // \"CASH\", \"VIETQR\"\n  status        String      @default(\"COMPLETED\") // PENDING, COMPLETED, CANCELLED\n  orderNote     String?\n  createdAt     DateTime    @default(now())\n  items         OrderItem[]\n}\n\n// 4. Chi Tiết Từng Món Trong Đơn Hàng\nmodel OrderItem {\n  id        String  @id @default(uuid())\n  orderId   String\n  order     Order   @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  productId String\n  product   Product @relation(fields: [productId], references: [id])\n  qty       Int     @default(1)\n  price     Float\n  itemNote  String? // Ghi chú pha chế: \"Ít đường, nhiều đá...\"\n}\n\n// 5. Nhân Viên\nmodel Staff {\n  id          String     @id @default(uuid())\n  name        String\n  role        String // \"Phục vụ\", \"Thu ngân\", \"Pha chế\"\n  wagePerHour Float      @default(25000)\n  createdAt   DateTime   @default(now())\n  orders      Order[]\n  shiftLogs   ShiftLog[]\n}\n\n// 6. Quản Lý Ca Làm & Chấm Công\nmodel ShiftLog {\n  id        String   @id @default(uuid())\n  staffId   String\n  staff     Staff    @relation(fields: [staffId], references: [id], onDelete: Cascade)\n  date      DateTime @default(now())\n  shiftType String // \"Sáng\", \"Chiều\", \"Tối\"\n  hours     Float    @default(4)\n  tips      Float    @default(0)\n}\n\n// 7. Quản Lý Kho & Nguyên Vật Liệu\nmodel Ingredient {\n  id          String       @id @default(uuid())\n  name        String // \"Hạt Robusta\", \"Sữa đặc\", \"Syrup Đào\"...\n  unit        String // \"g\", \"ml\", \"hộp\"\n  stockQty    Float        @default(0)\n  costPerUnit Float        @default(0)\n  recipeItems RecipeItem[]\n}\n\n// 8. Định Lượng Công Thức Pha Chế (Món ăn <-> Nguyên liệu)\nmodel RecipeItem {\n  id           String     @id @default(uuid())\n  productId    String\n  product      Product    @relation(fields: [productId], references: [id], onDelete: Cascade)\n  ingredientId String\n  ingredient   Ingredient @relation(fields: [ingredientId], references: [id], onDelete: Cascade)\n  amount       Float // Số lượng nguyên liệu dùng cho 1 ly\n}\n",
